INSERT INTO ingredients (group_id, name, location, category, homemade, components, prep_note, position) SELECT g.id, 'Tomates', 'fridge', 'vegetables', 0, NULL, NULL, (SELECT COALESCE(MAX(i.position), 0) + 1 FROM ingredients i WHERE i.group_id = g.id) FROM ingredient_groups g JOIN restaurants r ON r.id = g.restaurant_id WHERE g.name_fr = 'Pizza' AND (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%');
