-- Home-made preparations (made from other ingredients) for both restaurants, and the raw tomatoes they need.
UPDATE ingredients SET homemade = 1, components = '["Tomates"]', prep_note = 'Couper en cubes' WHERE name = 'Tomates en cubes' AND group_id IN (SELECT g.id FROM ingredient_groups g JOIN restaurants r ON r.id = g.restaurant_id WHERE (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%'));
UPDATE ingredients SET homemade = 1, components = '["Tomates"]', prep_note = 'Trancher' WHERE name = 'Tomates en tranches' AND group_id IN (SELECT g.id FROM ingredient_groups g JOIN restaurants r ON r.id = g.restaurant_id WHERE (r.name LIKE '%Sauveur%' OR r.name LIKE '%Agathe%'));
